file_editor: {"command": "create", "path": "/tmp/smoke.js", "file_text": "// Headless smoke test: load index.html in jsdom, run scripts, verify DOM.
const { JSDOM, ResourceLoader } = require('jsdom');
const path = require('path');

class LocalLoader extends ResourceLoader {
    fetch(url, options) {
        if (url.startsWith('file://')) return super.fetch(url, options);
        // Rewrite http(s) requests to local files (shouldn't happen here)
        return super.fetch(url, options);
    }
}

const outDir = '/root/output';
const url = 'file://' + outDir + '/index.html';

JSDOM.fromFile(outDir + '/index.html', {
    url,
    runScripts: 'dangerously',
    resources: new LocalLoader(),
    pretendToBeVisual: true,
}).then(async dom => {
    // Wait for scripts + d3.csv promise to resolve
    await new Promise(r => setTimeout(r, 1500));
    const doc = dom.window.document;

    const rows = doc.querySelectorAll('#stock-table tbody tr');
    const bubbles = doc.querySelectorAll('.bubble-group');
    const legendItems = doc.querySelectorAll('.legend-item');
    console.log('table rows:', rows.length);
    console.log('bubbles:',    bubbles.length);
    console.log('legend items:', legendItems.length);

    // Sample first 3 table rows
    rows.forEach((r, i) => {
        if (i < 3 || i >= rows.length - 3) {
            const cells = [...r.querySelectorAll('td')].map(td => td.textContent);
            console.log('row', i, '->', cells.join(' | '));
        }
    });

    // Check bubble label + circle radius on a couple bubbles
    ['AAPL', 'SPY', 'HFC'].forEach(t => {
        const g = doc.querySelector(`.bubble-group[data-ticker="${t}"]`);
        if (!g) { console.log(t, 'MISSING'); return; }
        const c = g.querySelector('circle');
        const label = g.querySelector('text');
        const tf = g.getAttribute('transform');
        console.log(t, 'r=' + c.getAttribute('r'), 'fill=' + c.getAttribute('fill'), 'label=' + label.textContent, 'transform=' + tf);
    });

    // Try a click on a bubble and confirm row highlights
    const aaplGroup = doc.querySelector('.bubble-group[data-ticker="AAPL"]');
    aaplGroup.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
    const selectedRow = doc.querySelector('#stock-table tbody tr.selected');
    const selectedCircle = doc.querySelector('.bubble-group[data-ticker="AAPL"] circle.selected');
    console.log('after clicking AAPL bubble -> selected row ticker:', selectedRow && selectedRow.getAttribute('data-ticker'));
    console.log('after clicking AAPL bubble -> circle has selected class:', !!selectedCircle);

    // Click a table row (MSFT) and confirm bubble highlights
    const msftRow = doc.querySelector('#stock-table tbody tr[data-ticker="MSFT"]');
    msftRow.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
    const nowSelectedCircle = doc.querySelector('circle.selected');
    console.log('after clicking MSFT row -> selected circle ticker:',
        nowSelectedCircle && nowSelectedCircle.parentNode.getAttribute('data-ticker'));

    // Hover an ETF -> tooltip should NOT become visible; hover a stock -> tooltip visible
    const tooltip = doc.querySelector('#tooltip');
    const spyGroup = doc.querySelector('.bubble-group[data-ticker="SPY"]');
    spyGroup.dispatchEvent(new dom.window.MouseEvent('mouseover', { bubbles: true }));
    console.log('after hovering SPY (ETF) -> tooltip classes:', tooltip.className);

    const nvdaGroup = doc.querySelector('.bubble-group[data-ticker="NVDA"]');
    nvdaGroup.dispatchEvent(new dom.window.MouseEvent('mouseover', { bubbles: true }));
    console.log('after hovering NVDA -> tooltip classes:', tooltip.className);
    console.log('tooltip HTML:', tooltip.innerHTML.slice(0, 200));

    // Sanity: ensure no bubble is outside SVG bounds
    let outOfBounds = 0;
    doc.querySelectorAll('.bubble-group').forEach(g => {
        const tf = g.getAttribute('transform');
        const m = /translate\(([-\d.]+),\s*([-\d.]+)\)/.exec(tf);
        if (!m) return;
        const x = parseFloat(m[1]), y = parseFloat(m[2]);
        const r = parseFloat(g.querySelector('circle').getAttribute('r'));
        if (x - r < 0 || x + r > 720 || y - r < 0 || y + r > 640) outOfBounds++;
    });
    console.log('bubbles out of bounds:', outOfBounds);
}).catch(err => { console.error('ERR', err); process.exit(1); });
